#!/bin/bash
# =============================================================================
# Provisioning script Inès / NOVA KIN — ComfyUI sur Vast.ai
# Reconstruit à partir des métadonnées réelles d'une image de production
# (RunComfy_examples_1507, workflow "Famegrid Spice" ID 1507), + LoRA v6.
#
# Idempotent : relancer ce script ne re-télécharge que ce qui manque.
# Premier boot : ~40-60 min selon la bande passante (~35-40 Go).
# Boots suivants (disque conservé, instance stoppée pas détruite) : quasi instantané.
#
# Variables d'environnement à définir dans le template Vast.ai AVANT de lancer :
#   HF_TOKEN       -> ton token HuggingFace (accès krea/Krea-2-Raw / Comfy-Org/Krea-2)
#   CIVITAI_TOKEN  -> ton token API Civitai (Settings > API Keys sur civitai.com)
#   GDRIVE_LORA_ID -> 1OYjCzvi3T7FgThb-cVPjkzum-hJrt7xT (déjà résolu, LoRA v6 confirmé sur ton Drive)
# =============================================================================
set -eo pipefail
COMFY_DIR="/workspace/ComfyUI"
cd "$COMFY_DIR" || { echo "ComfyUI introuvable dans $COMFY_DIR — vérifie que le template est bien un template ComfyUI"; exit 1; }

echo "=== [1/5] Custom nodes ==="
cd custom_nodes

# RES4LYF -> fournit ClownsharKSampler_Beta (sampler 2 passes utilisé en prod)
[ -d "RES4LYF" ] || git clone https://github.com/ClownsharkBatwing/RES4LYF/
pip install -r RES4LYF/requirements.txt --quiet || true

# Impact Pack + Subpack -> fournit FaceDetailer + UltralyticsDetectorProvider
[ -d "ComfyUI-Impact-Pack" ] || git clone https://github.com/ltdrdata/ComfyUI-Impact-Pack
[ -f "ComfyUI-Impact-Pack/.installed" ] && true || (cd ComfyUI-Impact-Pack && python install.py && touch .installed)
[ -d "ComfyUI-Impact-Subpack" ] || git clone https://github.com/ltdrdata/ComfyUI-Impact-Subpack

# Identity Edit (utilisé sur le workflow alternatif "identity edit" d'Inès)
[ -d "comfyui-krea2edit" ] || git clone https://github.com/lbouaraba/comfyui-krea2edit

cd "$COMFY_DIR"

echo "=== [2/5] Modèles de base (Krea 2 Raw repackagé ComfyUI, non gated) ==="
mkdir -p models/diffusion_models models/text_encoders models/vae models/loras models/ultralytics/bbox

download_hf() {
  # $1 = repo, $2 = chemin dans le repo, $3 = destination locale
  if [ ! -f "$3" ]; then
    echo "  -> téléchargement $2"
    hf download "$1" "$2" --local-dir /tmp/hf_dl --token "$HF_TOKEN"
    mv "/tmp/hf_dl/$2" "$3"
  else
    echo "  -> déjà présent : $3 (skip)"
  fi
}

download_hf "Comfy-Org/Krea-2" "diffusion_models/krea2_raw_bf16.safetensors" "models/diffusion_models/krea2_raw_bf16.safetensors"
download_hf "Comfy-Org/Krea-2" "text_encoders/qwen3vl_4b_bf16.safetensors" "models/text_encoders/qwen3vl_4b_bf16.safetensors"
download_hf "Comfy-Org/Krea-2" "loras/krea2_turbo_lora_rank_64_bf16.safetensors" "models/loras/krea2_turbo_lora_rank_64_bf16.safetensors"

# VAE — ⚠️ point à confirmer : les métadonnées de prod pointent vers "Wan2_1_VAE_fp32.safetensors".
# Le repo public le plus proche est Comfy-Org/Wan_2.1_ComfyUI_repackaged (nommé wan_2.1_vae.safetensors, pas fp32).
# Si le rendu diverge de la référence, c'est le premier point à vérifier.
if [ ! -f "models/vae/Wan2_1_VAE_fp32.safetensors" ]; then
  echo "  -> téléchargement VAE (à vérifier, cf. commentaire ci-dessus)"
  hf download "Comfy-Org/Wan_2.1_ComfyUI_repackaged" "split_files/vae/wan_2.1_vae.safetensors" --local-dir /tmp/hf_dl --token "$HF_TOKEN"
  mv "/tmp/hf_dl/split_files/vae/wan_2.1_vae.safetensors" "models/vae/Wan2_1_VAE_fp32.safetensors"
fi

echo "=== [3/5] LoRA filter bypass (Civitai, nécessite CIVITAI_TOKEN) ==="
if [ ! -f "models/loras/krea2filterbypass3.safetensors" ]; then
  wget -O "models/loras/krea2filterbypass3.safetensors" \
    "https://civitai.com/api/download/models/3067151?token=${CIVITAI_TOKEN}"
else
  echo "  -> déjà présent (skip)"
fi

echo "=== [4/5] LoRA identité v6 (Google Drive) ==="
if [ ! -f "models/loras/inesdn_lora_v6_KREA_2800.safetensors" ]; then
  pip install gdown --quiet
  gdown --id "${GDRIVE_LORA_ID:-1OYjCzvi3T7FgThb-cVPjkzum-hJrt7xT}" \
    -O "models/loras/inesdn_lora_v6_KREA_2800.safetensors"
  # ⚠️ Le fichier Drive doit être partagé en "Anyone with the link" pour que gdown fonctionne sans OAuth.
else
  echo "  -> déjà présent (skip)"
fi

echo "=== [4bis/5] Modèle de détection visage (FaceDetailer) ==="
if [ ! -f "models/ultralytics/bbox/face_yolov8m.pt" ]; then
  wget -O "models/ultralytics/bbox/face_yolov8m.pt" \
    "https://huggingface.co/Bingsu/adetailer/resolve/main/face_yolov8m.pt"
fi

echo "=== [5/5] Workflow auto-chargé (Famegrid Spice 1507, LoRA v6, recette recalibrée) ==="
mkdir -p user/default/workflows
cat > user/default/workflows/ines_famegrid_spice_v6.json << 'WORKFLOW_JSON'
